"""Fixed routes; credentials are headers, never model arguments."""
from .twin_mcp import ID
PAYLOAD = dict(type='object', description='Exact mission payload documented at /static/missions.html. Registered file distribution or resource calibration inputs and authorized confirmations only.')
ROUTES = {
 'mission_capabilities': ('GET','/capabilities','missions:read',{},(), 'Read registered missions, learning rule, input bounds and evidence limits.'),
 'mission_list': ('GET','','missions:read',{},(), 'List own persistent missions.'),
 'mission_create': ('POST','','missions:write',{'payload':PAYLOAD},('payload',), 'Create a private registered mission. First read mission_capabilities and /static/missions.html. File distribution payload: idempotency_key (16–64 letters/digits/_/-), files (name:text map, up to 16 and 65536 bytes total), processing_permission=true, technical_scope_acknowledged=true. Resource calibration payload: kind=resource_calibration_v1, calibration={context,resource,unit,baseline,max_underprediction,data_kind,training,validation}, idempotency_key and the same confirmations. Observations have id,value,observed_at (timezone required),source; integer values 0..1000000, at least 3 training then 2 later validation records, at most 32 total. With parent_mission_id omit baseline; the completed own parent supplies it and context/resource/unit/data_kind must match, all records must be newer. A private estimate artifact may adopt a training-only median when holdout error strictly improves and maximum underprediction does not worsen or exceed the declared limit. Retrospective evidence only. Alternatively, forecast_mission_id with calibration={validation:[new later records]} uses the completed own forecast observations as training and its frozen estimate as baseline; partial forecasts cannot train. Context, units, tolerance and source type are inherited. Only provide confirmations within granted authority. Does not start execution.'),
 'mission_get': ('GET','/{id}','missions:read',{'id':ID},('id',), 'Read own mission status, durable stage and result.'),
 'mission_export': ('GET','/{id}/export','missions:read',{'id':ID},('id',), 'Export own mission input and empirical memory.'),
 'mission_artifact': ('GET','/{id}/artifact','missions:read',{'id':ID},('id',), 'Read verified private archive or resource estimate JSON as base64 with SHA-256.'),
 'mission_run': ('POST','/{id}/run','missions:run',{'id':ID},('id',), 'Queue or explicitly resume an own mission within shared execution quotas. A completed mission is reused. Effects are limited to its private downloadable artifact; no external actions.'),
 'mission_forecast': ('GET','/{id}/forecast','missions:read',{'id':ID},('id',), 'Read own frozen estimate, received observations and complete report. Server receipt order does not independently attest event times or sources.'),
 'mission_freeze': ('POST','/{id}/forecast','missions:write',{'id':ID,'payload':PAYLOAD},('id','payload'), 'Freeze a completed own resource estimate before receiving observations. Payload: artifact_sha256 and expected_count (integer 3..30). Estimate, baseline, context, tolerance and sample count are immutable. Does not execute an external action.'),
 'mission_observe': ('POST','/{id}/observations','missions:write',{'id':ID,'payload':PAYLOAD},('id','payload'), 'Append one authorized observation to own forecast. Payload: forecast_sha256 and observation={id,value,observed_at,source}. Server records receipt time. Declared event must be after freezing and prior event, and no later than receipt. ID is idempotent; content cannot be changed. Exactly the predetermined count closes the report; this scores frozen estimates without refitting them.'),
 'mission_cancel': ('POST','/{id}/cancel','missions:run',{'id':ID},('id',), 'Cancel own pending execution; durable history remains until deletion.'),
 'mission_context_get': ('GET','/{id}/context-forecast','missions:read',{'id':ID},('id',), 'Read own contextual forecast plan, predictions, observations, status and native report. Sources and event times are declared, not independently attested.'),
 'mission_context_freeze': ('POST','/{id}/context-forecast','missions:write',{'id':ID,'payload':PAYLOAD},('id','payload'), 'Freeze a contextual plan from a completed own calibration. Payload: artifact_sha256, warmup_count (3..10), scored_count (6..30). Baseline is the accepted estimate; resource, unit, tolerance and data kind are inherited. Four strategies use only previous observations. The selection rule is fixed before targets arrive; no external action.'),
 'mission_context_predict': ('POST','/{id}/context-forecast/predictions','missions:write',{'id':ID,'payload':PAYLOAD},('id','payload'), 'Issue and persist predictions BEFORE observing the next target. Payload: forecast_sha256, prediction_id (1..64 letters/digits/_/-). The server chooses using prior scored errors in the same context. At most one prediction can await an observation. Retry the same ID after a lost response; do not substitute a new measurement.'),
 'mission_context_observe': ('POST','/{id}/context-forecast/observations','missions:write',{'id':ID,'payload':PAYLOAD},('id','payload'), 'Submit the later target for the pending prediction. Payload: forecast_sha256, prediction_sha256, observation={id,value,observed_at,source}. Observation ID must equal prediction_id. Value is integer 0..1000000; declared event must be later than server prediction and no later than receipt. Exact retry is idempotent, changed content rejected. Fixed count becomes ready_to_close, not a completed native report.'),
 'mission_context_close': ('POST','/{id}/context-forecast/close','missions:run',{'id':ID,'payload':PAYLOAD},('id','payload'), 'Close a fully observed contextual plan with native verification in a bounded process. Payload: forecast_sha256. Uses shared compiler capacity and execution quotas. Failure preserves observations for explicit retry. Completed reports are immutable and retries reuse them without consuming execution quota. Assesses the adaptive policy as executed, not a post-hoc winner; no wellbeing or PVS inference.'),
 'mission_delete': ('DELETE','/{id}','missions:delete',{'id':ID,'confirm':dict(type='boolean',const=True)},('id','confirm'), 'Erase own mission, checkpoints, inputs and artifact, recording a backup privacy tombstone.'),
}
def definitions(tool):
    return [tool(name,description,props,required,scope=scope,read=method=='GET',destructive=method=='DELETE')
            for name,(method,path,scope,props,required,description) in ROUTES.items()]
def execute(name,args,authorization,rest):
    method,path,*_ = ROUTES[name]
    payload = args.get('payload', {'confirm':True} if name=='mission_delete' else {})
    return rest(method,'/api/missions'+path.format(**args),payload if method!='GET' else None,authorization)
